//! Boxes generated by `::before` and `::after` through the paths a window takes:
//! the kept tree, the cascade run again for a hover, and the text a hover adds.

use florui::prelude::*;
use florui_reactive::use_signal;
use florui_test::{Harness, Route, assert_matches_clean, by_id};

const CSS: &str = "\
    .list { width: 220px; } \
    .row { height: 20px; background-color: #f0f0f0; } \
    .row::before { content: \"- \"; color: #2040c0; } \
    .row:hover::after { content: \" <\"; color: #c02020; } \
    .row:hover { background-color: #cce0ff; }";

const ROWS: usize = 8;

fn list(shift: usize) -> Element {
    let rows: Vec<Element> = (0..ROWS)
        .map(|i| {
            Element::node(
                "div",
                vec![("class".into(), "row".into())],
                vec![Element::text(format!("Row {}", i + shift))],
            )
        })
        .collect();
    Element::node(
        "div",
        vec![
            ("id".into(), "list".into()),
            ("class".into(), "list".into()),
        ],
        rows,
    )
}

fn harness(shift: usize) -> Harness {
    Harness::new(move || list(shift))
        .css(CSS)
        .viewport(240.0, 200.0)
}

#[test]
fn hovering_across_rows_with_a_generated_box_matches_pointing_at_the_last_one() {
    assert_matches_clean(
        "generated_hover_across_rows",
        Route::new(harness(0), |m| {
            let list = m.get(by_id("list"));
            let b = m.bounds(list).expect("the list is drawn");
            for step in 0..6 {
                m.move_pointer(b.x + 30.0, b.y + 10.0 + step as f32 * 20.0);
            }
        }),
        Route::new(harness(0), |m| {
            let list = m.get(by_id("list"));
            let b = m.bounds(list).expect("the list is drawn");
            m.move_pointer(b.x + 30.0, b.y + 10.0 + 5.0 * 20.0);
        }),
    );
}

#[test]
fn a_hover_adds_the_text_of_the_generated_box_and_leaving_takes_it_away() {
    let mut mounted = harness(0).mount();
    let list = mounted.get(by_id("list"));
    let b = mounted.bounds(list).expect("the list is drawn");
    let before = mounted.frame();
    mounted.move_pointer(b.x + 30.0, b.y + 30.0);
    let hovered = mounted.frame();
    assert_ne!(before.rgba, hovered.rgba, "the hover paints something");
    mounted.move_pointer(b.x + 300.0, b.y + 30.0);
    let left = mounted.frame();
    assert_eq!(
        before.rgba, left.rgba,
        "leaving paints the first frame again"
    );
}

#[test]
fn a_tree_whose_text_changes_keeps_its_generated_boxes() {
    let counter = || {
        let n = use_signal(|| 0);
        let bumped = n.clone();
        view! {
            <div class="row" onclick={move || bumped.set(bumped.get() + 1)}>{n.get().to_string()}</div>
        }
    };
    assert_matches_clean(
        "generated_text_change",
        Route::new(Harness::new(counter).css(CSS).viewport(240.0, 60.0), |m| {
            let row = m.get(florui_test::by_class("row"));
            m.click(row);
            m.click(row);
        }),
        Route::new(
            Harness::new(|| {
                view! { <div class="row">{"2"}</div> }
            })
            .css(CSS)
            .viewport(240.0, 60.0),
            |m| {
                let row = m.get(florui_test::by_class("row"));
                m.hover(row);
            },
        ),
    );
}
